const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c <= 32) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const E = nextInt();
const M = nextInt();
const D = nextInt();

const friendsA = new Int32Array(M);
const friendsB = new Int32Array(M);
for (let i = 0; i < M; i++) {
  friendsA[i] = nextInt();
  friendsB[i] = nextInt();
}

const dislikesA = new Int32Array(D);
const dislikesB = new Int32Array(D);
for (let i = 0; i < D; i++) {
  dislikesA[i] = nextInt();
  dislikesB[i] = nextInt();
}

const group = new Int32Array(E + 1);
for (let g = 1; g <= E / 3; g++) {
  group[nextInt()] = g;
  group[nextInt()] = g;
  group[nextInt()] = g;
}

let violations = 0;
for (let i = 0; i < M; i++) {
  if (group[friendsA[i]] !== group[friendsB[i]]) violations++;
}
for (let i = 0; i < D; i++) {
  if (group[dislikesA[i]] === group[dislikesB[i]]) violations++;
}

console.log(violations);
